  eq(v.shape,sh,id..' shape')
  assert(v.dtype==dt,id..': dtype '..v.dtype..' vs '..dt)
  eq(v:tolist(),expected,id..' values')
 else eq(v,expected,id..' scalar') end
 assert(g:random()==after,id..' pcg64')
 n=n+1
end
